<script setup>
import { computed,reactive,ref } from 'vue'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import { display } from './fields.js'
const store=useDemo(),search=ref(''),error=ref(''),editing=ref(false),preview=ref(null),pending=ref(null),file=ref(null),model=reactive({})
const user=computed(()=>store.currentUser.value)
const events=computed(()=>store.visibleEvents.value)
const eventIds=computed(()=>new Set(events.value.map(e=>e.id)))
const rows=computed(()=>store.state.evidence.filter(e=>(eventIds.value.has(e.eventId)||e.uploadedBy===user.value?.id)&&`${e.name} ${e.type} ${e.sourceRef}`.toLowerCase().includes(search.value.toLowerCase())))
const attachable=computed(()=>events.value.filter(e=>e.status==='draft').map(e=>({label:`${e.ref||'Draft'} · ${e.type||'Event type pending'}`,value:e.id})))
const columns=[{name:'name',label:'Document',field:'name',align:'left',sortable:true},{name:'type',label:'Type',field:'type',align:'left',sortable:true},{name:'eventId',label:'Linked report',field:'eventId',align:'left'},{name:'status',label:'Availability',field:'status',align:'left'},{name:'actions',label:'',field:'id'}]
function event(id){return events.value.find(e=>e.id===id)}
function removable(item){return item.uploadedBy===user.value?.id&&(!item.eventId||event(item.eventId)?.status==='draft')}
function open(){Object.keys(model).forEach(k=>delete model[k]);Object.assign(model,{name:'',type:'Photograph',sourceRef:'',notes:'',eventId:null});file.value=null;error.value='';editing.value=true}
function save(){try{if(!model.name.trim()&&!file.value)throw Error('Enter a document name or select a local file.');if(model.eventId&&!attachable.value.some(e=>e.value===model.eventId))throw Error('New documents can be attached here only to your drafts. Use correction editing for a report under correction.');const entry=store.add('evidence',{...model,name:model.name.trim()||file.value.name,status:'reference_only',mime:file.value?.type||'',size:file.value?.size??null,uploadedBy:user.value.id,uploadedAt:new Date().toISOString()});if(model.eventId){const linked=event(model.eventId);store.saveEvent({...JSON.parse(JSON.stringify(linked)),evidenceIds:[...new Set([...linked.evidenceIds,entry.id])]})}editing.value=false;error.value=''}catch(e){error.value=e.message}}
function remove(){try{const item=pending.value;if(!removable(item))throw Error('Submitted evidence is retained with the report.');if(item.eventId){const linked=event(item.eventId);store.saveEvent({...JSON.parse(JSON.stringify(linked)),evidenceIds:linked.evidenceIds.filter(id=>id!==item.id)})}store.remove('evidence',item.id);pending.value=null;error.value=''}catch(e){error.value=e.message;pending.value=null}}
</script>
<template><div class="page-wrap"><PageHeader title="Evidence and documents" subtitle="Document metadata and source references for your reports. Selected files stay on your device."><template #actions><q-btn v-if="store.can('report')" color="primary" no-caps icon="attach_file" label="Add document metadata" @click="open"/></template></PageHeader><q-banner v-if="error&&!editing" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}</q-banner><section class="panel"><div class="toolbar-row"><q-input v-model="search" outlined dense clearable label="Search document or source reference" @clear="search=''"/><q-space/><span class="muted">Submitted source references are retained.</span></div><q-table :rows="rows" :columns="columns" row-key="id" flat :pagination="{rowsPerPage:10}" wrap-cells><template #body-cell-name="p"><q-td :props="p"><q-btn flat color="primary" no-caps :label="p.row.name" @click="preview=p.row"/><div class="muted text-caption">{{p.row.sourceRef||'Source reference not supplied'}}</div></q-td></template><template #body-cell-eventId="p"><q-td :props="p"><router-link v-if="event(p.row.eventId)" class="record-link" :to="`/reporter/reports/${p.row.eventId}?tab=evidence`">{{event(p.row.eventId).ref}}</router-link><span v-else>Unattached metadata</span></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn flat color="primary" no-caps label="View metadata" @click="preview=p.row"/><q-btn v-if="removable(p.row)" flat round color="negative" icon="delete_outline" aria-label="Remove unsubmitted metadata" @click="pending=p.row"/></q-td></template><template #no-data><div class="empty-state full-width"><q-icon name="folder_open" size="40px"/><p>{{search?'No documents match this search.':'No documents yet. Add a source reference or attach metadata while editing a report.'}}</p></div></template></q-table></section><q-dialog v-model="editing" persistent><q-card style="width:680px;max-width:95vw"><q-card-section class="text-h6">Add document metadata</q-card-section><q-card-section><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}</q-banner><div class="form-grid"><q-file v-model="file" outlined clearable label="Select local file (metadata only)"/><q-input v-model="model.name" outlined label="Document name"/><q-select v-model="model.type" :options="['Photograph','Master statement','Spot report','Certificate','Correspondence','Chart / position','Other']" outlined label="Document type"/><q-input v-model="model.sourceRef" outlined label="Source reference"/><q-select class="span-2" v-model="model.eventId" :options="attachable" emit-value map-options clearable outlined label="Attach to draft report (optional)"/><q-input class="span-2" v-model="model.notes" type="textarea" outlined label="Notes / evidence description" autogrow/></div><p class="muted q-mb-none">Only name, type, file size and references are retained. There is no upload server or stored copy of selected file contents.</p></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn color="primary" no-caps label="Save document metadata" @click="save"/></q-card-actions></q-card></q-dialog><q-dialog :model-value="!!preview" @update:model-value="preview=null"><q-card style="width:600px;max-width:95vw"><q-card-section class="row items-center"><strong class="text-h6">{{preview?.name}}</strong><q-space/><q-btn flat round icon="close" v-close-popup aria-label="Close document metadata"/></q-card-section><q-card-section><div v-for="[key,label] in [['type','Document type'],['sourceRef','Source reference'],['mime','File media type'],['size','File size (bytes)'],['status','Availability'],['notes','Notes'],['uploadedAt','Added at']]" :key="key" class="q-mb-md"><div class="muted">{{label}}</div><div>{{display(preview?.[key])}}</div></div><p class="muted">This preview shows retained metadata. It does not contain the original file.</p></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Close" v-close-popup/></q-card-actions></q-card></q-dialog><q-dialog :model-value="!!pending" @update:model-value="pending=null"><q-card style="max-width:430px"><q-card-section class="text-h6">Remove unsubmitted metadata?</q-card-section><q-card-section>{{pending?.name}} will be detached from its draft and removed from this browser.</q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Keep metadata" v-close-popup/><q-btn color="negative" no-caps label="Remove metadata" @click="remove"/></q-card-actions></q-card></q-dialog></div></template>
